entries[40767] = { ["name"] = "Überschallbooster", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+81 Ausdauer\nBenötigt Ingenieurskunst (390)\nAnlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 Sek. lang Eure Angriffskraft um 430. Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)\nVerkaufspreis:" }
entries[40768] = { ["name"] = "MOLL-E", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst (425)\nBenutzen: Erstellt 10 Min. lang einen tragbaren Briefkasten. MOLL-E wird nach seiner Nutzung nicht zerstört. (1 Stunde Abklingzeit)\n\"Mobiler optimierter Liebesbrief- und Lieferungsextraktor\"" }
entries[40769] = { ["name"] = "Konstruktionsset: Schrottbot", ["text"] = "Benötigt Ingenieurskunst (425)\nBenutzen: Erstellt einen mechanischen Schrottbot, der Ausrüstung repariert und fast alles kauft. Nach 5 Min. verschwindet er. (15 Min Abklingzeit)\nVerkaufspreis:" }
entries[40771] = { ["name"] = "Kobaltsplitterbombe", ["text"] = "Benötigt Ingenieurskunst (330)\nBenutzen: Fügt Zielen in einem Umkreis von 3 Metern 750 to 1000 Feuerschaden zu und macht sie 3 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[40772] = { ["name"] = "Gnomisches Armeemesser", ["text"] = "Benutzen: Ein Großmeister der Ingenieurskunst kann die Batterien des Messers überladen, um zu versuchen, einen toten Verbündeten ins Leben zurückzurufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\n\"Beinhaltet einen gyromatischen Mikroregler, einen Bogenlichtschraubenschlüssel, Feuerstein und Zunder, einen Schmiedehammer, eine Spitzhacke und ein Kürschnermesser.\"\nVerkaufspreis:" }
entries[40773] = { ["name"] = "Meisterlicher Feuerstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[40774] = { ["name"] = "Meisterlicher Zauberstein", ["text"] = "Benötigt Stufe 45\nVerkaufspreis:" }
entries[40775] = { ["name"] = "Geflügelter Greif der Schwarzen Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nKlassen: Todesritter\nBenötigt Stufe 60\nBenötigt Erfahrenes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Euren geflügelten Greif der Schwarzen Klinge oder gibt ihn wieder frei. Das ist ein Flugreittier." }
entries[40776] = { ["name"] = "Persönlicher elektromagnetischer Pulsgenerator", ["text"] = "Benötigt Ingenieurskunst (375)\nBenutzen: Bringt an einem Gürtel dauerhaft einen elektromagnetischen Pulsgenerator an, der es einem geschickten Ingenieur bei Aktivierung gestattet, nahe mechanische Einheiten zu verwirren.\n\nKann nur an Euren eigenen Gürtel angebracht werden und er wird dadurch seelengebunden.\nVerkaufspreis:" }
entries[40777] = { ["name"] = "Eisbärengeschirr", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt Stufe 60\nBenötigt Reiten (150)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren weißen Eisbär oder gibt ihn wieder frei." }
